// The existing CMS track field is the association; unknown tracks get no misleading map/photo.
export function getTrackVisual(track: string): TrackVisual | undefined {
  const value = track
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
  const aliases: [string, string[]][] = [
    ['spa', ['spa']],
    ['monza', ['monza']],
    ['nurburgring', ['nurburgring']],
    ['lemans', ['le mans', 'sarthe']],
    ['silverstone', ['silverstone']],
    ['imola', ['imola', 'enzo e dino ferrari']],
  ]
  const id = aliases.find(([, names]) => names.some((name) => value.includes(name)))?.[0]
  return tracks.find((track) => track.id === id)
}
